import { coverageHomes } from './coverage';
import { MARKETS } from './markets';
import { PHOTO_POOLS } from './images';
import { NEIGHBORHOOD_FOOTPRINTS, spreadInFootprint } from './neighborhoods';
import type { CountryCode, Furnishing, Nation, Property, PropertyType } from '../types/property';

/**
 * 200 fictional UK listings across London (120), Manchester (25),
 * Birmingham (20), Bristol (20) and Edinburgh (15). All prices are GBP.
 *
 * Cities and neighborhoods are real so markers cluster the way real listings
 * would, but every address is fictional on purpose: street names such as
 * "Sample Street", "Example Road" or "Placeholder Row" make that obvious and
 * avoid pointing at real homes. Coordinates are approximate points inside each
 * neighborhood, not buildings. Every fact on a row (price, size, pet policy,
 * bills, lease costs, …) is an invented demo value; titles and descriptions are
 * generated from those fields and say they are demo data. Sale prices are total
 * asking prices; rents are per calendar month. Every value is hard-coded, so
 * the dataset is the same on every build.
 *
 * Prices follow rough fictional £/m² bands per neighbourhood (prime central
 * London highest, regional cities far lower) so the relative order between
 * cities and areas looks credible. Detail facts follow a few listing profiles:
 * - student houses (3+ beds near universities): furnished, HMO licensed, all bills included, no pets;
 * - family lets (3+ beds elsewhere): mostly unfurnished, pets often considered, no bills included;
 * - flat shares (2 beds) and single lets (studios, 1 beds): mixed sharer, student and bills terms;
 * - English flats for sale are leasehold or share of freehold with lease costs; English houses freehold;
 * - Scottish homes use outright ownership (no leasehold), and Scottish deposits follow the two-month cap.
 * A field missing from a row means the listing does not state it — it is not a "no".
 *
 * London is deliberately the densest market, with heavier clusters in hot
 * neighborhoods (Shoreditch, Clapham, Hackney, Islington, Battersea, Canary
 * Wharf), mirroring the way Rightmove/Zoopla results concentrate in reality.
 */

/** A hand-written listing row; the city-level and generated fields are added by `city`. */
type Row = Omit<Property, 'id' | 'title' | 'description' | 'image' | 'imageAlt' | 'currency' | 'city' | 'countryCode' | 'nation' | 'lat' | 'lng'>;

/** A listing before its map position is assigned from its neighbourhood footprint. */
type Unplaced = Omit<Property, 'lat' | 'lng'>;

const TYPE_LABELS: Record<PropertyType, string> = {
  apartment: 'Apartment',
  house: 'House',
  townhouse: 'Townhouse',
  villa: 'Villa',
};

const ADJECTIVES = ['Bright', 'Renovated', 'Spacious', 'Light-filled', 'Quiet', 'Corner', 'Modern', 'Classic'] as const;

const FURNISHING_TEXT: Record<Furnishing, string> = {
  furnished: 'furnished',
  part_furnished: 'part-furnished',
  unfurnished: 'unfurnished',
};

function titleFor(row: Row, index: number): string {
  const adjective = ADJECTIVES[index % ADJECTIVES.length];
  const type = TYPE_LABELS[row.type].toLowerCase();
  const size = row.bedrooms === 0 ? 'studio' : `${row.bedrooms}-bedroom ${type}`;
  return `${adjective} ${size} in ${row.neighborhood}`;
}

function descriptionFor(row: Row, cityName: string): string {
  const baths = row.bathrooms === 1 ? '1 bathroom' : `${row.bathrooms} bathrooms`;
  const furnishing = row.furnishing ? `, offered ${FURNISHING_TEXT[row.furnishing]}` : '';
  const use = row.pricePeriod === 'monthly' ? 'to rent' : 'for sale';
  const type = TYPE_LABELS[row.type].toLowerCase();
  const article = /^[aeiou]/.test(type) ? 'An' : 'A';
  return `Demo listing with fictional details. ${article} ${type} ${use} in ${row.neighborhood}, ${cityName}, with ${baths}${furnishing}.`;
}

let listingIndex = 0;

const photoCursor: Record<PropertyType, number> = { apartment: 0, house: 0, townhouse: 0, villa: 0 };

function nextPhoto(type: PropertyType): string {
  const pool = PHOTO_POOLS[type];
  const photo = pool[photoCursor[type] % pool.length];
  photoCursor[type] += 1;
  return photo;
}

/** `firstNumber` lets a later block of rows continue a city's id sequence, so earlier ids never shift. */
function city(countryCode: CountryCode, nation: Nation, cityName: string, idPrefix: string, rows: Row[], firstNumber = 1): Unplaced[] {
  const { currency } = MARKETS[countryCode];
  return rows.map((row, i) => ({
    ...row,
    id: `${idPrefix}-${String(i + firstNumber).padStart(3, '0')}`,
    title: titleFor(row, listingIndex++),
    description: descriptionFor(row, cityName),
    image: nextPhoto(row.type),
    imageAlt: `${TYPE_LABELS[row.type]} in ${row.neighborhood}, ${cityName}`,
    currency,
    city: cityName,
    countryCode,
    nation,
  }));
}

