/**
 * Gives every listing a map position: the listings of one neighbourhood are
 * spread across that neighbourhood's footprint (in dataset order), so no two
 * share a point and none sits in a park or in the water.
 */
function place(listings: Unplaced[]): Property[] {
  const groups = new Map<string, Unplaced[]>();
  for (const p of listings) {
    const key = `${p.city}|${p.neighborhood}`;
    groups.set(key, [...(groups.get(key) ?? []), p]);
  }
  const positions = new Map<string, { lat: number; lng: number }>();
  for (const [key, group] of groups) {
    const [cityName, neighborhood] = key.split('|');
    const footprint = NEIGHBORHOOD_FOOTPRINTS[cityName]?.[neighborhood];
    if (!footprint) throw new Error(`No footprint for ${key}`);
    spreadInFootprint(footprint, group.length, key).forEach((pos, i) => positions.set(group[i].id, pos));
  }
  return listings.map((p) => ({ ...p, ...positions.get(p.id)! }));
}

